package com.wtm.importer;
import com.wtm.employee.*; import java.nio.file.Path; import java.time.LocalDate; import java.util.*;
public final class EmployeeDamagePerformanceImporter{private EmployeeDamagePerformanceImporter(){}public static Result preview(Path f,EmployeeStore.Snapshot s)throws Exception{CsvTable t=CsvTable.read(f);if(!new DamageKpiProfile().supports(t))return new Result(List.of(),List.of());List<PerformanceRecord>r=new ArrayList<>();List<String>w=new ArrayList<>();Set<String>seen=new HashSet<>();for(Map<String,String>x:t.rows()){LocalDate d=DamageKpiProfile.date(DamageKpiProfile.first(x,"date","damagedate","eventdate","completeddate"));String i=DamageKpiProfile.first(x,"employeenumber","employee","shortname","user","username","completeduser","completeduserbk","causedby");if(d==null||i.isBlank())continue;EmployeeProfile e=find(s,i);if(e==null){w.add("Damage record could not be matched to employee: "+i);continue;}String detail=DamageKpiProfile.first(x,"damage","damagetype","description","item","part","partnumber");String k=e.id()+"|"+d+"|"+detail;if(!seen.add(k))continue;r.add(new PerformanceRecord("",e.id(),d,"Damage",1,0," incident","CSV_DAMAGES",detail.isBlank()?"Imported damage incident.":"Imported damage incident: "+detail));}return new Result(r,w);}public static void apply(EmployeeStore.Snapshot s,Result x){for(PerformanceRecord n:x.records()){boolean exists=s.performance.stream().anyMatch(r->r.employeeId().equals(n.employeeId())&&Objects.equals(r.date(),n.date())&&r.metric().equalsIgnoreCase("Damage")&&r.source().equalsIgnoreCase("CSV_DAMAGES")&&r.notes().equals(n.notes()));if(!exists)s.performance.add(n);}}private static EmployeeProfile find(EmployeeStore.Snapshot s,String x){String w=n(x);for(EmployeeProfile e:s.employees)if(n(e.employeeNumber()).equals(w)||n(e.shortName()).equals(w)||n(e.name()).equals(w))return e;return null;}private static String n(String v){return v==null?"":v.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}public record Result(List<PerformanceRecord>records,List<String>warnings){public Result{records=records==null?List.of():List.copyOf(records);warnings=warnings==null?List.of():List.copyOf(warnings);}}}